import math

def babylonian_squareroot(number, tolerance=1e-12, max_iterations=1000):
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    if number == 0 or number == 1:
        return float(number)
    guess = number / 2.0
    for _ in range(max_iterations):
        prev = guess
        guess = (prev + number / prev) / 2.0
        if abs(guess - prev) < tolerance:
            break
    return guess

# Example usage:
if __name__ == "__main__":
    for val in [0, 1, 2, 9, 16, 25, 123456789]:
        print(f"sqrt({val}) = {babylonian_squareroot(val):.12f}  (math.sqrt = {math.sqrt(val):.12f})")

