import re

def valid_date(date):
    """You have to write a function which validates a given date string and
    returns True if the date is valid otherwise False.
    The date is valid if all of the following rules are satisfied:
    1. The date string is not empty.
    2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy
    """    
    if not date or not isinstance(date, str):
        return False
    # Regular expression to match mm-dd-yyyy with leading zeros allowed
    pattern = r'^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-(\d{4})$'
    match = re.match(pattern, date)
    if not match:
        return False
    month, day, year = int(match.group(1)), int(match.group(2)), int(match.group(3))
    # Days in month
    if month in {1,3,5,7,8,10,12}:
        if day < 1 or day > 31:
            return False
    elif month in {4,6,9,11}:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False
    else:
        return False
    return True

def common_element(list1, list2):
    """Return True if list1 and list2 share at least one element, False otherwise."""
    # Convert one list to a set for O(n) lookups
    set1 = set(list1)
    # Return True if any element from list2 is in set1
    return any(item in set1 for item in list2)

