from typing import Any, Dict

def dict_depth(d: Dict[Any, Any]) -> int:
    """
    Return the maximum depth of nested dictionaries in `d`.
    An empty or non-dictionary input yields 0.
    """
    if not isinstance(d, dict) or not d:
        return 0

    def _depth(obj):
        if not isinstance(obj, dict) or not obj:
            return 1
        return 1 + max(_depth(v) for v in obj.values())

    return _depth(d) - 1  # subtract 1 to consider the outermost dict as depth 1

