def is_multiply_prime(a):
    """Return True if the given number is the product of exactly three prime numbers (counting multiplicity),
    otherwise False.  The number a is assumed to be less than 100.

    Examples:
    >>> is_multiply_prime(30)
    True
    >>> is_multiply_prime(8)
    True
    >>> is_multiply_prime(12)
    False
    """
    if a < 2:
        return False

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # count prime factors with multiplicity
    count = 0
    n = a
    for p in range(2, int(n**0.5) + 1):
        while n % p == 0:
            if not is_prime(p):
                return False
            count += 1
            n //= p
            if count > 3:
                return False
    if n > 1:  # n itself is a prime factor
        if not is_prime(n):
            return False
        count += 1

    return count == 3

