def set_left_most_unset_bit(n: int) -> int:
    """
    Return an integer equal to n with the leftmost (most significant) unset bit set to 1.
    The search for the leftmost unset bit starts at the most significant set bit of n
    and moves towards the least significant bit.  If all bits up to the most
    significant set bit are 1, the next higher bit is set.
    """
