from typing import Dict

def _split_fields(line: str):
    """Yield each field token respecting quoted semicolons."""
    part = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '"':
            # toggle quote state, but don't add the quote to the part
            in_quotes = not in_quotes
            part.append(ch)
        elif ch == ';' and not in_quotes:
            token = ''.join(part).strip()
            if token:
                yield token
            part = []
        else:
            part.append(ch)
        i += 1
    # last part
    token = ''.join(part).strip()
    if token:
        yield token

def _unquote_value(val: str) -> str:
    """Remove surrounding double quotes and interpret escaped quotes."""
    if len(val) >= 2 and val[0] == '"' and val[-1] == '"':
        inner = val[1:-1]
        # replace escaped quotes
        return inner.replace('\\"', '"')
    return val

def parse_record(line: str) -> Dict[str, object]:
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.
    """
    result: Dict[str, object] = {}
    for token in _split_fields(line):
        if '=' in token:
            key, value = token.split('=', 1)
            key = key.strip()
            value = value.strip()
            # Handle quoted value
            if value.startswith('"') and value.endswith('"'):
                value = _unquote_value(value)
            else:
                value = value.strip()
            result[key] = value
        else:
            key = token.strip()
            if key:
                result[key] = True
    return result

