import re

def parse_record(line: str) -> dict:
    """
    Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    def split_fields(s: str):
        fields = []
        current = []
        in_quotes = False
        escape = False
        for ch in s:
            if escape:
                current.append(ch)
                escape = False
                continue
            if ch == '\\':
                escape = True
                current.append(ch)  # keep it for now; will be processed later if inside quotes
                continue
            if ch == '"':
                in_quotes = not in_quotes
                current.append(ch)
                continue
            if ch == ';' and not in_quotes:
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        fields.append(''.join(current))
        return fields

    def parse_field(field: str):
        field = field.strip()
        if not field:
            return None, None
        if '=' in field:
            key, value = field.split('=', 1)
            key = key.strip()
            # value may be quoted
            value = value.strip()
            if value.startswith('"') and value.endswith('"'):
                # remove outer quotes
                inner = value[1:-1]
                # unescape \" inside
                inner = inner.replace(r'\"', '"')
                inner = inner.replace(r'\\', '\\')
                return key, inner
            else:
                # plain value: trim whitespace
                return key, value.strip()
        else:
            key = field.strip()
            return key, True

    result = {}
    for field in split_fields(line):
        key, val = parse_field(field)
        if key is not None:
            result[key] = val
    return result

