def find_lists(Input):
    """
    Count the number of lists present in the given tuple,
    including nested lists at any depth.

    Parameters:
        Input (tuple): The tuple to inspect.

    Returns:
        int: The total number of list objects found.
    """
    if not isinstance(Input, tuple):
        raise TypeError("Input must be a tuple")

    def count_lists(obj):
        if isinstance(obj, list):
            return 1
        if isinstance(obj, tuple) or isinstance(obj, list):
            return sum(count_lists(item) for item in obj)
        return 0

