def set_left_most_unset_bit(n: int) -> int:
    """
    Return the integer obtained by setting the most significant unset bit (0)
    in the binary representation of n. If all bits up to the highest set bit
    are 1, the next higher bit is set.

    Examples:
        set_left_most_unset_bit(5)  # 5 is 0b101 -> 7 (0b111)
        set_left_most_unset_bit(7)  # 7 is 0b111 -> 15 (0b1111)
        set_left_most_unset_bit(8)  # 8 is 0b1000 -> 14 (0b1110)
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    m = n.bit_length() - 1  # highest set bit index
    for i in range(m, -1, -1):
        if (n >> i) & 1 == 0:
            return n | (1 << i)
    # all bits up to m are 1, set the next higher bit
    return n | (1 << (m + 1))

