def comb_sort(nums):
    """Sort a list of comparable elements using the Comb sort algorithm."""
    if len(nums) < 2:
        return nums.copy()
    gap = len(nums)
    shrink = 1.3
    swapped = True
    result = nums.copy()
    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(0, len(result) - gap):
            if result[i] > result[i + gap]:
                result[i], result[i + gap] = result[i + gap], result[i]
                swapped = True
    return result

