def next_Perfect_Square(N):
    """
    Return the smallest perfect square strictly greater than N.
    """
    import math
    k = math.isqrt(N)  # largest integer whose square <= N
    if k * k > N:
        return k * k
    else:
        return (k + 1) * (k + 1)

