def extract_freq(test_list):
    """
    Returns the count of unique tuples in the provided list.

    Parameters
    ----------
    test_list : list
        List containing hashable elements, typically tuples.

    Returns
    -------
    int
        Number of distinct tuple elements in the list.
    """
    unique = set()
    for item in test_list:
        # Ensure item is hashable; skip non-hashable items
        try:
            unique.add(item)
        except TypeError:
            # If item is not hashable (e.g., list), convert to a tuple if possible
            if isinstance(item, (list, set)):
                try:
                    unique.add(tuple(item))
                except Exception:
                    pass
            # Otherwise, ignore the item
    return len(unique)

def recursive_list_sum(data_list):
