from typing import List

def large_product(nums1: List[int], nums2: List[int], N: int) -> List[int]:
    """
    Returns the N largest products formed by selecting one element from nums1 and one from nums2.
    If N exceeds the total number of possible products, all products are returned sorted in descending order.
    """
    if not nums1 or not nums2 or N <= 0:
        return []

    # Generate all possible products
    products = [a * b for a in nums1 for b in nums2]

    # If N is larger than or equal to the number of products, just sort all
    if N >= len(products):
        return sorted(products, reverse=True)

    # Use heapq.nlargest to efficiently get the N largest values
    return heapq.nlargest(N, products)

