import re

def valid_date(date: str) -> bool:
    """
    Validates a date string in the format mm-dd-yyyy.
    """
    if not date:
        return False

    # Basic format check: mm-dd-yyyy with hyphens
    pattern = r"^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])-(\d{4})$"
    match = re.match(pattern, date)
    if not match:
        return False

    month, day, year = map(int, match.groups())

    # Check month value (already okay by regex but keep for safe)
    if month < 1 or month > 12:
        return False

    # Check day ranges per month
    if month in {1, 3, 5, 7, 8, 10, 12}:
        if day < 1 or day > 31:
            return False
    elif month in {4, 6, 9, 11}:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True

