def get_max_sum(n: int) -> int:
    """Return the maximum sum defined by:
       f(n) = max(n, f(n//2)+f(n//3)+f(n//4)+f(n//5))
    """
    memo = {0: 0}

    def helper(x: int) -> int:
        if x in memo:
            return memo[x]
        val = helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5)
        memo[x] = max(x, val)
