import math

def _parse_value(val):
    """
    Convert an integer, float, or string representation of a real number
    (using '.' or ',' as the decimal separator) into a float.
    If the input is already an int or float, it is returned unchanged.
    """
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        # Replace comma with dot to handle European decimal separator
        val_std = val.replace(",", ".")
        try:
            return float(val_std)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {val}")
    raise TypeError(f"Unsupported type: {type(val).__name__}")

def compare_one(a, b):
    """
    Compare two values that can be integers, floats, or strings representing
    real numbers. Return the larger variable in its original type. If the
    values are equal (after numeric conversion), return None.
    """
    # Attempt to parse both values to floats for comparison
    try:
        num_a = _parse_value(a)
        num_b = _parse_value(b)
    except (TypeError, ValueError):
        # If parsing fails, fall back to direct comparison (not required by spec)
        return None

    # Compare numeric values
    if num_a > num_b:
        return a
    if num_b > num_a:
        return b
    # They are numerically equal
    return None

def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries within `d`.
    Depth of a plain dictionary with no nested dictionaries is 1.
    """
    if not isinstance(d, dict):
        return 0
    max_subdepth = 0
    for v in d.values():
        subdepth = dict_depth(v)
        if subdepth > max_subdepth:
            max_subdepth = subdepth
    return 1 + max_subdepth

