def is_undulating(n):
    """
    Returns True if the decimal representation of n alternates
    between increasing and decreasing digits, i.e. each consecutive
    difference has an opposite sign to the previous difference.
    Numbers with less than 3 digits are considered undulating.
    """
    s = str(abs(n))
    if len(s) <= 2:
        return True

    digits = [int(c) for c in s]
    # compute first non-zero difference
    diff_prev = None
    for i in range(1, len(digits)):
        diff = digits[i] - digits[i - 1]
        if diff == 0:
            return False  # equal digits break the pattern
        if diff_prev is None:
            diff_prev = diff
        else:
            if (diff_prev > 0 and diff > 0) or (diff_prev < 0 and diff < 0):
                return False
            diff_prev = diff
    return True

