from functools import lru_cache

@lru_cache(maxsize=None)
def _newman_conway(n: int) -> int:
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1 or n == 2:
        return 1
    if n % 2 == 0:          # n is even: n = 2k
        k = n // 2
        return _newman_conway(k) + _newman_conway(k + 1)
    else:                   # n is odd: n = 2k + 1
        k = n // 2
        return _newman_conway(k + 1)

