import re

def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal,
      \\" is an escaped quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    def _split_fields(s):
        """Return list of field strings, splitting on ';' outside quotes."""
        fields = []
        buf = []
        in_quote = False
        escape = False
        for ch in s:
            if escape:
                buf.append(ch)
                escape = False
                continue
            if ch == '\\' and in_quote:
                escape = True
                buf.append(ch)  # keep the escape for later processing
                continue
            if ch == '"':
                in_quote = not in_quote
                buf.append(ch)
            elif ch == ';' and not in_quote:
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        if buf:
            fields.append(''.join(buf))
        return fields

    def _unescape_quoted_value(qv):
        # qv includes surrounding quotes
        inner = qv[1:-1]
        # replace \\" with " and \\ with \
        return inner.replace(r'\\"', '"').replace(r'\\', '\\')

    result = {}
    for field in _split_fields(line):
        if not field.strip():
            continue
        if '=' in field:
            key, val = field.split('=', 1)
            key = key.strip()
            val = val.strip()
            if val.startswith('"') and val.endswith('"'):
                # quoted value; keep as is except unescape and strip quotes
                val = _unescape_quoted_value(val)
            else:
                val = val.strip()
            result[key] = val
        else:
            key = field.strip()
            if key:
                result[key] = True
    return result

